(* [comment removed for export] *)
Theorem art_allocate3_small :
  forall (Q : list aev -> machine_state -> Prop) (log : list aev) regs (M0 rom : word -> option byte) (raw : word)
         (sp HI n stk tp key tsd ctx t loff spb ris qs km l2 blk trp szt rl rz qz rs qr qn m8 : Z) (kb : nat) (inited : bool) (cl : art_cls),
    let c := AsanTab.class_id (rs + rz) in
    let w := art_ca_cptr c cl in
    let ab := spb + c * 2 ^ 32 + w * 16 in
    let shb := 2147450880 + 8192 * qs + c * 2 ^ 29 in
    getr regs 1 = raw -> ret_ok raw -> getr regs 2 = Z_to_bv 64 sp -> getr regs 4 = Z_to_bv 64 tp -> getr regs 10 = Z_to_bv 64 1468568 ->
    getr regs 11 = Z_to_bv 64 n -> getr regs 12 = Z_to_bv 64 8 -> getr regs 13 = Z_to_bv 64 stk -> getr regs 14 = Z_to_bv 64 1 -> getr regs 15 = Z_to_bv 64 1 ->
    (* [comment removed for export] *)
    1 <= n < 8 -> rl = AsanTab.rz_log n -> rz = 16 * 2 ^ rl -> rz = 16 * qz -> 1 <= qz <= 128 ->
    n = 8 * qn + m8 -> 0 <= m8 <= 7 -> rs = 8 * qr -> n <= rs <= n + 7 -> rs + rz <= 65536 ->
    (* [comment removed for export] *)
    art_geo HI t ctx tp tsd spb ris qs -> HI <= sp - 1952 -> HI + 4096 <= sp -> sp + 2144 <= 2 ^ 47 -> sp <= stk -> stk + 16 <= sp + 4096 ->
    0 <= trp < 2 ^ 64 -> 0 <= szt < 2 ^ 64 -> sp <= trp -> trp + 8 * szt <= sp + 4096 ->
    0 <= loff -> 0x10000 <= tp + loff -> tp + loff + 4 <= 0x6c0000 -> 0x68bde8 <= tp - 88 -> 0x68bde8 <= tsd ->     (* [comment removed for export] *)
    (* [comment removed for export] *)
    l2 + 2 ^ 20 <= HI -> blk + 2 ^ 23 <= HI ->
    apart l2 (2 ^ 20) t 4096 -> apart l2 (2 ^ 20) ctx 4096 -> apart l2 (2 ^ 20) spb (2 ^ 37 + 4096) -> apart l2 (2 ^ 20) 0x7fff7000 (0x10007fff8000 - 0x7fff7000) ->
